package net.civeira.phylax.features.document.snippetversion.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ContentTextVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property content text of snippet version ")
  void test_content_text_v_o_builder() {
    Assertions.assertFalse(ContentTextVO.nullValue().getContentText().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ContentTextVO.tryFrom(null).getContentText().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ContentTextVO.from("one").getContentText().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ContentTextVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ContentTextVO.from("one").toString());
  }
}
